package wt

import (
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"strings"

	"github.com/mukeshmk/devex-manager/internal/gitx"
)

const confTemplate = `# DevEx Manager Configuration
# This file was generated by 'git wt clone'.
# Edit the values below to customize worktree behavior for this repository.

[repo]
# The default base branch for creating new worktrees.
base_branch = %BRANCH%

# The name of the primary worktree directory.
main_worktree_name = %BRANCH%

[symlinks]
# Comma-separated list of files and directories to symlink from the main worktree
# into each new worktree. Paths are relative to the worktree root.
# Symlinked paths share the same underlying file — changes in one worktree
# are reflected in all others.
paths =

[copies]
# Comma-separated list of files and directories to copy from the main worktree
# into each new worktree. Paths are relative to the worktree root.
# Use 'git wt sync' to synchronize changes across worktrees.
paths = .claude,.kiro,.vscode

[worktree]
# How to derive the worktree folder name from the branch name.
# Options:
#   ticket-prefix  - Use first two hyphen-delimited segments (e.g., JIRA-1234)
#   full-branch    - Use the full branch name (/ replaced with --)
#   custom         - Use a custom folder name passed as the last argument to 'git wt add'
naming_strategy = ticket-prefix
`

// Clone sets up <cwd>/<name>/.git as a bare clone plus a worktree for the default branch.
// Parity with git-wt-clone.
func Clone(url, cwd string, out io.Writer) error {
	name := strings.TrimSuffix(path.Base(strings.TrimRight(url, "/")), ".git")
	dir := filepath.Join(cwd, name)
	fmt.Fprintf(out, "Setting up bare clone for %s...\n", name)
	if es, _ := os.ReadDir(dir); len(es) > 0 {
		return fmt.Errorf("Error: Directory '%s' already exists and is not empty.", name)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	step := func(s string, args ...string) error {
		fmt.Fprintln(out, s)
		_, err := gitx.Run(dir, args...)
		return err
	}
	if err := step("[1/5] Cloning bare repository...", "clone", url, "--bare", ".git"); err != nil {
		return err
	}
	bare := filepath.Join(dir, ".git")
	if err := step("[2/5] Configuring remote fetch...", "--git-dir="+bare, "config", "remote.origin.fetch", "+refs/heads/*:refs/remotes/origin/*"); err != nil {
		return err
	}
	if err := step("[3/5] Fetching origin...", "--git-dir="+bare, "fetch", "origin"); err != nil {
		return err
	}
	branch, err := gitx.Run(dir, "--git-dir="+bare, "symbolic-ref", "--short", "HEAD")
	if err != nil || branch == "" {
		branch = "main"
	}
	fmt.Fprintf(out, "Detected default branch: %s\n", branch)
	if err := step(fmt.Sprintf("[4/5] Creating '%s' worktree...", branch), "worktree", "add", "./"+branch, branch); err != nil {
		return err
	}
	fmt.Fprintln(out, "[5/5] Generating DevEx config...")
	conf := filepath.Join(dir, ".devex.conf")
	if exists(conf) {
		fmt.Fprintf(out, "Warning: Config file already exists at %s, preserving it.\n", conf)
	} else {
		if err := os.WriteFile(conf, []byte(strings.ReplaceAll(confTemplate, "%BRANCH%", branch)), 0o644); err != nil {
			return err
		}
		fmt.Fprintf(out, "Config file created: %s\n", conf)
	}
	fmt.Fprintln(out, "\n✓ Bare clone and worktree created successfully!")
	return nil
}
